{"packet_id": "D053-01", "doc_id": "D053", "jurisdiction": "MA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Damages for reprisals against a tenant", "requirement": "A landlord may not threaten or take reprisals against a residential tenant for enforcing housing law, reporting code violations or joining a tenants' union; violation carries damages of one to three months' rent, or actual damages if greater, plus costs and fees.", "key_value": "1 to 3 months' rent", "coverage_conditions": "Tenants of residential premises in Massachusetts who enforce housing law, report violations to a board or the landlord, or organize or join a tenants' union.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": "Damages not less than one month's rent and not more than three month's rent, or the actual damages sustained by the tenant, whichever is greater, plus costs of suit including a reasonable attorney's fee.", "effective_date": null, "citation": "G.L. c. 186, § 18: reprisals against tenants", "quoted_span": "shall be liable for damages which shall not be less than one month's rent or more than three month's rent, or the actual damages sustained by the tenant, whichever is greater, and the costs of the suit, including a reasonable attorney's fee.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D053-01", "doc_id": "D053", "jurisdiction": "MA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Rebuttable presumption of reprisal for termination or rent increase", "requirement": "A termination notice other than for nonpayment, a rent increase or a substantial change in tenancy terms within six months of a protected activity is presumed to be a reprisal, rebuttable only by clear and convincing evidence.", "key_value": "6 months", "coverage_conditions": "Tenants who commenced, proceeded with or obtained relief in such an action, exercised such rights, complained, or organized or joined a tenants' union, or where another person acted for them or in the building.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "G.L. c. 186, § 18: rebuttable presumption of reprisal", "quoted_span": "The receipt of any notice of termination of tenancy, except for nonpayment of rent, or, of increase in rent, or, of any substantial alteration in the terms of tenancy within six months after the tenant has commenced, proceeded with, or obtained relief in such action, exercised such rights, made such report or complaint, or organized or joined such tenants' union or within six months after any other person has taken such action or actions on behalf of the tenant or in, or relating to, the building in which the tenant resides, shall create a rebuttable presumption that such notice or other action is a reprisal against the tenant for engaging in such activities.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
